<script setup lang="ts">import type { SaveSlot } from '../types'; defineProps<{ open: boolean; mode: 'load' | 'manage'; slots: SaveSlot[]; currentId: string | null }>(); defineEmits<{ close: []; load: [id: string]; remove: [id: string] }>()</script>
<template><Transition name="fade"><div v-if="open" class="modal-overlay z-[100]" @click.self="$emit('close')"><div class="save-dialog"><div class="panel-title">{{ mode === 'load' ? '载入存档' : '存档管理' }}</div><div v-if="!slots.length" class="py-8 text-center text-ink-fade">尚无存档记录。</div><div v-else class="mb-4 max-h-[350px] overflow-y-auto"><div v-for="s in slots" :key="s.id" class="save-slot" @click="mode === 'load' && $emit('load', s.id)"><div><div class="slot-info">{{ s.id === currentId ? '● ' : '' }}{{ s.sect_name || '未命名' }} — 第{{ s.year }}年第{{ s.month }}月 <span v-if="s.id === currentId" class="text-xs text-cinnabar">（当前）</span></div><div class="slot-time">声望{{ s.prestige }} · 库银{{ s.silver }}两 · {{ s.disciples }}名弟子 · {{ s.updated_at ? new Date(s.updated_at).toLocaleString('zh-CN') : '' }}</div></div><div><button v-if="mode !== 'load'" class="btn btn-sm" @click.stop="$emit('load', s.id)">载入</button> <button class="btn btn-sm" @click.stop="$emit('remove', s.id)">删除</button></div></div></div><button class="btn" @click="$emit('close')">返回</button></div></div></Transition></template>

